function Metric({label,value,icon:Icon,children,alert}){return <div className={'metric card '+(alert?'alert-metric':'')}><div className="metric-top"><span>{label}</span><Icon size={17}/></div><div className="metric-value">{value}</div><div className="metric-bottom">{children}</div></div>}
function TaskTable({tasks,s,onEdit,onUpdate,onSub,onProject}){const ordered=[];const ids=new Set(tasks.map(t=>t.id));const add=t=>{ordered.push(t);tasks.filter(c=>c.parentId===t.id).forEach(add)};tasks.filter(t=>!t.parentId||!ids.has(t.parentId)).forEach(add);tasks=ordered;return <div className="table-scroll"><ResponsiveTable className="data-table task-table"><thead><tr><th>Task / workstream</th><th>Resource</th><th>Target</th><th>Predecessors</th><th>Progress</th><th>Status</th><th/></tr></thead><tbody>{tasks.map(t=>{const summary=s.tasks.some(x=>x.parentId===t.id),preds=t.predecessors.map(id=>s.tasks.find(x=>x.id===id)?.title);return <tr key={t.id} className={t.parentId?'subtask-row':''}><td><button className="task-name" onClick={()=>onEdit(t)}>{t.parentId?<span className="subtask-line">↳</span>:summary?<Layers3 size={15}/>:<span className="task-square"/>}<strong>{t.isMilestone?'◆ ':''}{t.title}</strong></button><small className="task-project">{s.projects.find(p=>p.id===t.projectId)?.title}{summary?' · Summary task':''}</small></td><td><span className="resource-name">{s.users.find(u=>u.id===t.assigneeId)?.name||t.resource}</span><small>{t.department}</small></td><td>{dateLabel(t.due)}<small>{t.effort}h planned</small>{taskVariance(s,t).original&&<small>Baseline: {taskVariance(s,t).original.due}</small>}</td><td><span className="predecessor" title={preds.join(', ')}>{preds.length?<><Link2 size={13}/>{preds.length} prerequisite{preds.length>1?'s':''}</>:'—'}</span></td><td><div className="task-progress"><Progress value={progress(s,t.projectId,t.id)}/><b>{progress(s,t.projectId,t.id)}%</b></div></td><td><Badge status={taskStatus(s,t)}/><VarianceBadge state={s} task={t}/></td><td>{summary?(canPlan(s.user,t.department)&&<button className="icon-button" title="Add subtask" aria-label={'Add subtask to '+t.title} onClick={()=>onSub(t)}><Plus size={16}/></button>):(canUpdate(s.user,t)&&<button className="text-link" onClick={()=>onUpdate(t)}>Update<ArrowUpRight size={14}/></button>)}</td></tr>})}</tbody></ResponsiveTable></div>}
